    try: [{ act: '切「偏信陀螺(α=0.98)」', watch: '融=30.24°≈陀螺30.2°：平滑抗抖，靠 2% 加速度慢慢纠漂。' }, { act: '切「均衡(α=0.5)」', watch: '融=31.1°：一半跟加速度、纠漂快但明显发抖。' }, { act: '想两个极端', watch: '只陀螺→bias 无限漂；只加速度→抖得没法用。互补两全。' }], terms: [],
